-- Varikotsele (HARD) amaliy test bankini to'ldirish — 50 ta savol,
-- HTML maqola (ta'rif, epidemiologiya, patofiziologiya, klinik, diagnostika, davolash, asoratlar) asosida.
-- Amaliy test bo'limi shulardan random 20 tasini shuffle qilib chiqaradi.
UPDATE public.dars_tarkibi
SET savollar_banki = $savollar$[{"savol":"Varikosele nima sababli yuzaga keladi?","variantlar":["Arteriya bosimining oshishi","Venoz klapanlar yetishmovchiligi (valvular incompetence) natijasida reflyuks","Limfa tomirlarining tiqilishi","Urug' bezi to'qimasining yallig'lanishi"],"togri":1,"izoh":"Varikosele venalar klapanlarining yetishmovchiligi natijasida vena qonining orqaga qaytishi (venoz reflyuks) tufayli yuzaga keladi."},{"savol":"Dubin-Amelar tasnifi bo'yicha, faqat instrumental tekshiruvda (Dopler UTT) aniqlanadigan, palpatsiya qilinmaydigan varikosele qaysi daraja deyiladi?","variantlar":["I-daraja","II-daraja","Subklinik","III-daraja"],"togri":2,"izoh":"Subklinik varikosele palpatsiya qilinmaydi va ko'rinmaydi, faqat Dopler UTT orqali aniqlanadi."},{"savol":"I-daraja (yengil) varikosele qanday aniqlanadi?","variantlar":["Tinch holatda ham ko'zga ko'rinadi","Faqat bemor tik turgan holatda Valsalva sinamasi vaqtida palpatsiya qilinadi","Faqat yotgan holatda palpatsiya qilinadi","Hech qachon palpatsiya qilinmaydi"],"togri":1,"izoh":"I-daraja — faqat Valsalva sinamasi (kuchanish) vaqtida, tik turgan holatda palpatsiya qilinadi."},{"savol":"II-daraja (o'rtacha) varikosele haqida qaysi gap to'g'ri?","variantlar":["Faqat Doppler UTT'da aniqlanadi","Valsalva sinamasisiz ham palpatsiya qilinadi, lekin ko'zga ko'rinmaydi","Ko'z bilan aniq ko'rinadi","Faqat o'smirlarda uchraydi"],"togri":1,"izoh":"II-daraja Valsalva sinamasisiz ham qo'l bilan palpatsiya qilinadi, ammo ko'zga ko'rinmaydi."},{"savol":"III-daraja (og'ir) varikosele qanday tavsiflanadi?","variantlar":["Faqat USI'da ko'rinadi","Moshonka terisi (rugae) orqali ko'zga ko'rinadi va osongina palpatsiya qilinadi","Faqat Valsalva bilan aniqlanadi","Hech qanday belgi bermaydi"],"togri":1,"izoh":"III-daraja eng og'ir shakl bo'lib, ko'z bilan ko'rinadi ('qurt to'plami' ko'rinishi) va osongina palpatsiya qilinadi."},{"savol":"Varikosele necha foiz hollarda chap tomonda uchraydi?","variantlar":["~50%","~90%","~25%","~10%"],"togri":1,"izoh":"Varikosele taxminan 90% hollarda chap tomonlama uchraydi, bu anatomik sabablarga bog'liq."},{"savol":"Subklinik varikoseleni davolash bo'yicha klinik eslatmaga ko'ra nima to'g'ri?","variantlar":["Albatta jarrohlik kerak","Reproduktiv salohiyatni sezilarli yaxshilamaydi, odatda kuzatiladi","Faqat antibiotik bilan davolanadi","Darhol embolizatsiya qilinadi"],"togri":1,"izoh":"Ko'pchilik tadqiqotlar subklinik varikoseleni davolash fertillikni sezilarli yaxshilamasligini ko'rsatadi, shu sabab odatda kuzatiladi."},{"savol":"Izolyatsiyalangan o'ng tomonlama varikosele aniqlansa, ayniqsa keskin boshlangan bo'lsa, birinchi navbatda nimani inkor etish zarur?","variantlar":["Qandli diabetni","Retroperitoneal patologiyani (masalan, buyrak o'smasi)","Oshqozon yarasini","Astma kasalligini"],"togri":1,"izoh":"O'ng tomonlama izolyatsiyalangan varikosele kamdan-kam uchraydi va retroperitoneal massa (masalan buyrak hujayrali karsinoma) tomonidan venoz drenajning bosilishidan shubhalanish kerak."},{"savol":"Umumiy erkaklar populyatsiyasida varikoselening tarqalish chastotasi taxminan qancha?","variantlar":["~5%","~15%","~50%","~75%"],"togri":1,"izoh":"Umumiy erkaklar populyatsiyasida varikosele taxminan 15% (har 5-6 erkakdan 1 tasi) uchraydi."},{"savol":"Ikkinchi darajali (sekundar) infertillik bilan murojaat qiluvchilarda varikosele chastotasi qancha?","variantlar":["~10%","~35%","75-81%","~5%"],"togri":2,"izoh":"Sekundar infertillik bilan murojaat qiluvchilarda varikosele chastotasi 75-81% gacha yetadi."},{"savol":"Infertil erkaklarning umumiy qancha qismida varikosele aniqlanadi?","variantlar":["5-10%","1/3-1/2 (33-50%)","90% dan ortiq","Deyarli hech kimda"],"togri":1,"izoh":"Infertil erkaklarning taxminan 1/3 dan 1/2 gachasida (33-50%) varikosele aniqlanadi."},{"savol":"Chap urug' venasi chap buyrak venasiga qanday burchak ostida va qaysi balandlikda quyiladi?","variantlar":["Qiya burchak ostida, pastroq","To'g'ri burchak ostida, o'ng tomondagidan 8-10 sm yuqorida","Spiral shaklda","Bevosita pastki kovak venaga"],"togri":1,"izoh":"Chap urug' venasi chap buyrak venasiga to'g'ri burchak ostida, o'ng tomondagidan 8-10 sm yuqorida quyiladi — bu uzunroq gidrostatik bosim ustunini yaratadi."},{"savol":"O'ng urug' venasining pastki kovak venaga qiya burchak ostida quyilishi nimani ta'minlaydi?","variantlar":["Qon bosimini oshiradi","'Tabiiy klapan' effektini yaratib, reflyuksdan himoya qiladi","Venoz turg'unlikni kuchaytiradi","Hech qanday ahamiyati yo'q"],"togri":1,"izoh":"O'ng tomondagi qiya burchak 'tabiiy klapan' vazifasini bajarib, reflyuksning oldini oladi — shu sabab varikosele o'ng tomonda kamroq uchraydi."},{"savol":"Varikoseleda genetik moyillik haqida qaysi fikr to'g'ri?","variantlar":["Genetik aloqa yo'q","Birinchi darajali qarindoshlarda bu holat ko'proq uchraydi","Faqat onadan o'tadi","Faqat ayollarda namoyon bo'ladi"],"togri":1,"izoh":"Varikoseleli erkaklarning birinchi darajali qarindoshlarida bu holat ko'proq uchraydi, bu venoz klapan defektiga genetik moyillik borligini ko'rsatadi."},{"savol":"Pampiniform pleksusning normal fiziologik vazifasi nima?","variantlar":["Spermani saqlash","Qarama-qarshi oqim issiqlik almashinuvi orqali moshonka haroratini pasaytirish","Testosteron ishlab chiqarish","Siydikni filtratsiya qilish"],"togri":1,"izoh":"Pampiniform pleksus qarama-qarshi oqim issiqlik almashinuvini ta'minlab, moshonka haroratini tana haroratidan 2-4°C past saqlaydi — bu spermatogenez uchun zarur."},{"savol":"Varikoselede intratestikulyar harorat nima sababli ko'tariladi?","variantlar":["Qon ketishi tufayli","Issiqlik almashinuvi mexanizmi buzilgani uchun","Bakterial infeksiya tufayli","Gormonlar ko'payishi tufayli"],"togri":1,"izoh":"Varikoselede qarama-qarshi oqim issiqlik almashinuvi mexanizmi buziladi, natijada intratestikulyar harorat ko'tariladi va spermatogenez bevosita buziladi."},{"savol":"Venoz turg'unlik (venous stasis) urug' bezida nimaga olib keladi?","variantlar":["Qon bosimi pasayishiga","Gipoksiya va toksik metabolitlarning to'planishiga","Harorat pasayishiga","Hech qanday o'zgarishga"],"togri":1,"izoh":"Qonning turg'un holda to'planishi urug' bezida gipoksiya va toksik metabolitlarning to'planishiga olib keladi."},{"savol":"Oksidativ stress spermatozoidlarga qanday ta'sir qiladi?","variantlar":["Harakatchanlikni oshiradi","DNK fragmentatsiyasini kuchaytiradi va apoptozga moyillikni oshiradi","Hajmni oshiradi","Hech qanday ta'siri yo'q"],"togri":1,"izoh":"Varikoseleli bemorlarning urug'ida yuqori oksidativ stress spermatozoidlar DNKsining fragmentatsiyasini kuchaytiradi va apoptozni oshiradi."},{"savol":"Quyidagilardan qaysi biri varikoselening qo'shimcha patofiziologik mexanizmlariga kiradi?","variantlar":["Spermatozoidlarda aneuploidiyaga moyillik","Qon guruhi o'zgarishi","Suyak to'qimasi zararlanishi","Ko'z to'r pardasi shikastlanishi"],"togri":0,"izoh":"Boshqa mexanizmlar qatorida spermatozoidlarda aneuploidiyaga moyillik, hujayra ichi metabolik buzilish va apoptozga aloqador mikroRNK darajasining oshishi kiradi."},{"savol":"Yirik varikoseleler kichiklariga nisbatan qanday ta'sir ko'rsatadi?","variantlar":["Kamroq zararlanishga olib keladi","Odatda ko'proq zararlanishga olib keladi","Hech qanday farq yo'q","Faqat estetik muammo tug'diradi"],"togri":1,"izoh":"Yirikroq varikoseleler odatda kichikroqlariga nisbatan ko'proq urug' bezi zararlanishiga olib keladi."},{"savol":"Uzoq muddatli varikosele natijasida urug' bezida qanday o'zgarishlar yuzaga keladi?","variantlar":["Hajm kattalashadi, spermatogenez kuchayadi","Atrofiya, spermatogenez pasayishi va Leydig hujayralari funksiyasi buzilishi","Hech qanday o'zgarish bo'lmaydi","Faqat rang o'zgaradi"],"togri":1,"izoh":"Progressiv, davomiylikka bog'liq zararlanish natijasida urug' bezi atrofiyasi, spermatogenez pasayishi va androgen yetishmovchiligi (Leydig hujayralari funksiyasi buzilishi) kuzatiladi."},{"savol":"Varikoselening eng ko'p uchraydigan klinik kechishi qanday?","variantlar":["Kuchli og'riq bilan","Asimptomatik (belgisiz)","Yuqori harorat bilan","Qon ketishi bilan"],"togri":1,"izoh":"Ko'pchilik bemorlarda varikosele asimptomatik kechadi va tasodifan yoki infertillik tekshiruvi jarayonida aniqlanadi."},{"savol":"Varikoseleda og'riq odatda qachon kuchayadi va qachon kamayadi?","variantlar":["Yotganda kuchayadi, tik turganda kamayadi","Uzoq tik turish/zo'riqishdan keyin kuchayadi, yotganda kamayadi","Faqat tunda kuchayadi","Faqat ovqatlanishdan keyin kuchayadi"],"togri":1,"izoh":"Mosjonkadagi og'riq uzoq tik turish yoki jismoniy zo'riqishdan keyin kuchayadi, yotgan holatda kamayadi."},{"savol":"'Qurt to'plami' (bag of worms) ko'rinishi qaysi darajadagi varikoseleda kuzatiladi?","variantlar":["Subklinik","I-daraja","II-daraja","Og'ir (III) daraja"],"togri":3,"izoh":"Og'ir (III) darajali varikoselede ko'zga ko'rinadigan venalar to'plami 'qurt to'plami' ko'rinishini hosil qiladi."},{"savol":"Varikoseleni fizik tekshirishda bemor nega issiq xonada va tik turgan holatda tekshiriladi?","variantlar":["Bu shart emas, har qanday holatda tekshirilishi mumkin","Sovuqda kremaster mushagi qisqarib varikoseleni yashirib qo'yishi mumkin","Issiq xona qon bosimini oshiradi","Faqat bemorning qulayligi uchun"],"togri":1,"izoh":"Sovuq sharoitda kremaster mushagi qisqaradi va moyakni ko'taradi, bu varikoseleni yashirib, noto'g'ri (yolg'on negativ) natijaga olib kelishi mumkin."},{"savol":"Erkaklar reproduktologiya bo'limiga murojaat qilishning eng ko'p sababi nima?","variantlar":["Og'riq","Infertillik","Shish","Qichishish"],"togri":1,"izoh":"Infertillik — varikoseleli erkaklarning reproduktologga murojaat qilishining eng ko'p uchraydigan sababi."},{"savol":"Klinik eslatmaga ko'ra, varikoseleni to'g'ri aniqlash uchun bemorni qanday tekshirish zarur?","variantlar":["Faqat yotgan holatda","Tik turgan holatda va Valsalva sinamasi bilan","Faqat uxlagan holatda","Faqat rentgen orqali"],"togri":1,"izoh":"Kichik varikoseleler yotgan holatda osongina o'tkazib yuborilishi mumkin, shu sabab bemor albatta tik turgan holatda va Valsalva sinamasi bilan tekshirilishi kerak."},{"savol":"Varikoselening diagnostikasida birinchi navbatdagi asosiy usul qaysi?","variantlar":["KT","MRT","Klinik diagnoz (fizik tekshiruv)","Genomik tekshiruv"],"togri":2,"izoh":"Varikoselening diagnostikasi birinchi navbatda klinik diagnoz hisoblanadi — fizik tekshiruv (ko'rish va palpatsiya) asosiy usul."},{"savol":"Mosjonka Doppler ultratovush tekshiruvi qaysi chastotali datchiklar yordamida o'tkaziladi?","variantlar":["1-3 MHz","7.5-10 MHz","20-25 MHz","0.5-1 MHz"],"togri":1,"izoh":"Mosjonka Doppler UTT yuqori chastotali (7.5-10 MHz) datchiklar yordamida o'tkaziladi."},{"savol":"Doppler UTT qaysi holatda ko'rsatma hisoblanadi?","variantlar":["Har doim, birinchi tanlov sifatida","Klinik tekshiruv noaniq bo'lganda yoki jarrohlikdan keyin qoldiq/qaytalangan varikoseleni baholashda","Faqat bolalarda","Faqat ayollarda"],"togri":1,"izoh":"UTT klinik tekshiruv noaniq bo'lganda (masalan, lipoma tufayli) va jarrohlikdan keyin qoldiq yoki qaytalangan varikoseleni baholash uchun ko'rsatma hisoblanadi."},{"savol":"Yo'naltiruvchi tavsiyaga ko'ra, varikoseleni UTT'da aniqlash uchun vena diametri bo'yicha qanday holat mavjud?","variantlar":["Aniq, universal qabul qilingan chegara qiymati bor","Yagona universal chegara qiymati mavjud emas, bu munozarali masala","Faqat 1 mm dan katta bo'lsa varikosele hisoblanadi","Diametr ahamiyatsiz"],"togri":1,"izoh":"Varikoselening UTT'da aniqlanishi uchun vena diametri bo'yicha yagona, universal qabul qilingan chegara qiymati mavjud emas — bu adabiyotlarda hali munozarali."},{"savol":"Kompyuter tomografiya (KT) varikosele diagnostikasida qanday o'rin tutadi?","variantlar":["Birinchi tanlov usuli","Odatda birinchi tanlov emas, lekin chov sohasi patologiyasini baholashda foydali","Umuman ishlatilmaydi","Faqat bolalarda qo'llaniladi"],"togri":1,"izoh":"KT odatda birinchi tanlov usuli emas, lekin chov sohasi va urug' tizimchasi patologiyasini baholashda foydali bo'lishi mumkin."},{"savol":"MRT varikosele diagnostikasida qachon qo'llaniladi?","variantlar":["Har doim birinchi navbatda","Noaniq UTT topilmalarida ikkinchi qatorli tasvirlash usuli sifatida","Faqat jarrohlikdan oldin","Hech qachon qo'llanilmaydi"],"togri":1,"izoh":"MRT noaniq ultratovush topilmalarida ikkinchi qatorli tasvirlash usuli sifatida qo'llaniladi."},{"savol":"Venografiya asosan qachon qo'llaniladi?","variantlar":["Birinchi skrining usuli sifatida","Radiologik embolizatsiyadan oldin yoki davomida diagnostik/davolash maqsadida","Faqat bolalarda","Hech qachon qo'llanilmaydi"],"togri":1,"izoh":"Venografiya asosan radiologik embolizatsiyadan oldin yoki uning davomida diagnostik/davolash maqsadida qo'llaniladi."},{"savol":"Serum testosteron darajasi qancha bo'lganda gipoandrogenizm haqida gap boradi?","variantlar":["280-300 ng/dL dan past","1000 ng/dL dan yuqori","50 ng/dL dan past","Har qanday qiymatda"],"togri":0,"izoh":"Odatda serum testosteron darajasi 280-300 ng/dL dan past bo'lsa, gipoandrogenizm (androgen yetishmovchiligi) haqida gap boradi."},{"savol":"Gidroselening varikoseledan asosiy farqlovchi belgisi nima?","variantlar":["Transilluminatsiya pozitiv (yorug'lik o'tkazadi)","Faqat Valsalvada paydo bo'ladi","Venalar to'plami ko'rinishida bo'ladi","Faqat chap tomonda uchraydi"],"togri":0,"izoh":"Gidrosele suyuqlik to'plami bo'lgani uchun transilluminatsiya (yorug'lik o'tkazish) pozitiv bo'ladi va venalar tugunchasi bo'lmaydi — bu varikoseledan asosiy farqi."},{"savol":"Subklinik varikoseleda qanday yondashuv tavsiya etiladi?","variantlar":["Darhol jarrohlik","Dinamik kuzatuv (jarrohliksiz)","Doimiy antibiotikoterapiya","Embolizatsiya"],"togri":1,"izoh":"Subklinik varikosele (faqat instrumental usulda aniqlangan) holatida faol jarrohlik aralashuvisiz dinamik kuzatuv tavsiya etiladi."},{"savol":"O'smirlarda varikosele kuzatuvi qancha muddatda o'tkaziladi (agar urug' bezi hajmi normal bo'lsa)?","variantlar":["Har hafta","Har 6-12 oyda orkidometriya/UTT bilan","Faqat bir marta, keyin kerak emas","Har kuni"],"togri":1,"izoh":"O'smirlarda, agar urug' bezi hajmi va o'sishi normal bo'lsa, har 6-12 oyda orkidometriya/UTT bilan muntazam kuzatuv maqsadga muvofiq."},{"savol":"Varikoselening o'zini bartaraf etish bo'yicha qaysi fikr to'g'ri?","variantlar":["Samarali dori vositasi mavjud, faqat erta boshlash kerak","Samarali dori vositasi mavjud emas — bu faqat anatomik/jarrohlik muammosi","Faqat antibiotik bilan davolanadi","O'z-o'zidan har doim tuzaladi"],"togri":1,"izoh":"Varikoselening o'zini bartaraf etish uchun samarali dori vositasi mavjud emas — bu faqat anatomik/jarrohlik muammosi hisoblanadi."},{"savol":"Jarrohlik (varikoselektomiya) uchun asosiy ko'rsatmalardan biri qaysi?","variantlar":["Faqat estetik sabab","Klinik varikosele + patologik spermogramma + er-xotinning bola ko'rishga intilishi","Yoshning 18 dan oshganligi","Faqat o'ng tomonlama bo'lishi"],"togri":1,"izoh":"Asosiy ko'rsatmalardan biri — klinik (palpatsiya bilan aniqlanadigan) varikosele, patologik spermogramma ko'rsatkichlari va er-xotinning bola ko'rishga intilishi birikmasi."},{"savol":"Faqat ultratovushda aniqlangan, palpatsiya qilinmaydigan (subklinik) varikosele uchun jarrohlik haqida nima to'g'ri?","variantlar":["Har doim zarur","Tavsiya etilmaydi — samarali ta'siri isbotlanmagan","Faqat 20 yoshgacha amalga oshiriladi","Faqat o'ng tomonda amalga oshiriladi"],"togri":1,"izoh":"Subklinik varikosele uchun varikoselektomiya tavsiya etilmaydi, chunki semen ko'rsatkichlari yoki homiladorlik chastotasiga ishonchli ijobiy ta'siri isbotlanmagan."},{"savol":"Hozirgi 'oltin standart' jarrohlik usuli qaysi va nega?","variantlar":["Palomo usuli — eng arzon","Mikroxirurgik subingvinal/ingvinal varikoselektomiya — eng past qaytalanish va gidrosele ko'rsatkichlari","Laparoskopik usul — eng tez","Embolizatsiya — og'riqsiz"],"togri":1,"izoh":"Mikroxirurgik subingvinal/ingvinal varikoselektomiya eng past qaytalanish (0.5-1%) va gidrosele (0%) ko'rsatkichlari tufayli oltin standart hisoblanadi."},{"savol":"Laparoskopik varikoselektomiyaning o'ziga xos jiddiy asorat xavfi nimada?","variantlar":["Hech qanday jiddiy xavf yo'q","Ichak/tomir shikastlanishi, havo emboliyasi","Faqat teri rangi o'zgarishi","Faqat vaqtinchalik bosh og'rig'i"],"togri":1,"izoh":"Laparoskopik usulda boshqalardan farqli, ichak/tomir shikastlanishi va havo emboliyasi kabi jiddiy asoratlar xavfi mavjud."},{"savol":"Radiologik embolizatsiya usulida gidrosele xavfi qancha?","variantlar":["~30%","~12%","0%","~7%"],"togri":2,"izoh":"Radiologik embolizatsiya arteriya/limfa tomirlariga tegmagani uchun gidrosele xavfi 0% (lekin qaytalanish xavfi 15-25% bilan yuqoriroq)."},{"savol":"Varikoselektomiyadan keyin jinsiy aloqaga qaytish uchun tavsiya etilgan muddat qancha?","variantlar":["1 kun","1 hafta","1 oy","6 oy"],"togri":1,"izoh":"Operatsiyadan keyin jinsiy aloqaga qaytish odatda 1 hafta ichida tavsiya etiladi."},{"savol":"Varikoselektomiyadan keyin to'liq jismoniy faollikka qaytish uchun qancha vaqt kerak?","variantlar":["1 hafta","2 hafta","4 hafta","6 oy"],"togri":2,"izoh":"To'liq faollik odatda 4 hafta ichida tiklanadi (jinsiy aloqa — 1 hafta, yengil jismoniy yuklama — 2 hafta)."},{"savol":"Varikoselektomiyadan keyin spermogramma nazorati odatda qachon o'tkaziladi?","variantlar":["1 hafta","3-6 oydan keyin","5 yildan keyin","Umuman kerak emas"],"togri":1,"izoh":"Operatsiyadan keyin spermatogenez tiklanish vaqtini hisobga olib, spermogramma nazorati 3-6 oydan keyin o'tkaziladi."},{"savol":"Mikroxirurgik varikoselektomiyada gidrosele xavfi qancha foizni tashkil qiladi?","variantlar":["0%","~7%","~33%","~50%"],"togri":0,"izoh":"Mikroxirurgik usulda limfa tomirlari saqlanib qolgani uchun gidrosele xavfi 0% (klassik usullarda esa o'rtacha ~7%, 3-33% oraliqda)."},{"savol":"Varikoselektomiyadan keyingi qaytalanish (retsidiv) asosan nima sababli yuzaga keladi?","variantlar":["Bemorning yoshi tufayli","Periarterial mayda venalar/kollaterallarning saqlanib qolishi","Antibiotik qabul qilinmagani uchun","Operatsiyadan keyin sport bilan shug'ullanish"],"togri":1,"izoh":"Qaytalanish periarterial mayda venalar va kollaterallarning jarrohlik vaqtida bog'lanmasdan saqlanib qolishi natijasida yuzaga keladi."},{"savol":"Prognozga ko'ra, operatsiya yoshi qanchalik erta bo'lsa, natija qanday bo'ladi?","variantlar":["Natijaga ta'sir qilmaydi","Yaxshiroq natija va spermatogenez tiklanishi ehtimoli yuqori bo'ladi","Natija yomonlashadi","Faqat kattalar uchun yaxshi natija beradi"],"togri":1,"izoh":"Operatsiya yoshi qanchalik erta bo'lsa, shunchalik yaxshi natija va spermatogenez tiklanishi ehtimoli yuqori bo'ladi."}]$savollar$::jsonb,
    updated_at = now()
